package com.cpf.starter.security.secret;
import com.cpf.core.api.security.crypto.*;import java.security.*;import java.security.cert.Certificate;import java.util.*;
/** 이미 구성된 PKCS#11/JCA KeyStore를 사용하는 optional HSM provider입니다. PIN/private key 원문을 보관하지 않습니다. */
public final class CpfPkcs11KeyProvider implements CpfKeyProvider { private final KeyStore keyStore;private final Provider provider;public CpfPkcs11KeyProvider(KeyStore keyStore,Provider provider){this.keyStore=Objects.requireNonNull(keyStore);this.provider=Objects.requireNonNull(provider);}@Override public CpfSigningKey key(String keyId){try{Certificate c=keyStore.getCertificate(keyId);if(c==null)return new CpfSigningKey(keyId,"","UNKNOWN","",CpfKeyStatus.UNAVAILABLE);return new CpfSigningKey(keyId,"",c.getPublicKey().getAlgorithm(),c.getType(),CpfKeyStatus.ACTIVE);}catch(KeyStoreException e){throw new IllegalStateException("HSM key metadata unavailable",e);}}@Override public byte[] sign(String keyId,String algorithm,byte[] payload){try{Key key=keyStore.getKey(keyId,null);if(!(key instanceof PrivateKey pk))throw new IllegalStateException("Private signing key unavailable");Signature s=Signature.getInstance(algorithm,provider);s.initSign(pk);s.update(payload);return s.sign();}catch(GeneralSecurityException e){throw new IllegalStateException("HSM sign failed",e);}}@Override public boolean verify(String keyId,String algorithm,byte[] payload,byte[] signature){try{Certificate c=keyStore.getCertificate(keyId);if(c==null)return false;Signature s=Signature.getInstance(algorithm,provider);s.initVerify(c);s.update(payload);return s.verify(signature);}catch(GeneralSecurityException e){throw new IllegalStateException("HSM verify failed",e);}}}
